function validate([n, k, time]) {
  if (!Number.isInteger(n) || n < 1 || n > 10000) return 'n is between 1 and 10^4.';
  if (!Number.isInteger(k) || k < 1 || k > 10000) return 'k is between 1 and 10^4.';
  if (!Array.isArray(time) || time.length !== k) return 'time needs exactly k rows.';
  for (const row of time) {
    if (!Array.isArray(row) || row.length !== 4) return 'Each row of time has 4 values.';
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each time is between 1 and 1000.';
  }
  return null;
}

