function findCrossingTime(n, k, time) {
  const push = (heap, item, before) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0 && before(heap[i], heap[(i - 1) >> 1])) {
      const parent = (i - 1) >> 1;
      [heap[i], heap[parent]] = [heap[parent], heap[i]];
      i = parent;
    }
  };
  const pop = (heap, before) => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        let best = i;
        for (const child of [2 * i + 1, 2 * i + 2]) {
          if (child < heap.length && before(heap[child], heap[best])) best = child;
        }
        if (best === i) break;
        [heap[i], heap[best]] = [heap[best], heap[i]];
        i = best;
      }
    }
    return top;
  };
  // Waiting workers: the least efficient one (bigger crossing sum, then bigger index) comes out first.
  const cost = time.map(([right, , left]) => right + left);
  const slower = (a, b) => (cost[a] !== cost[b] ? cost[a] > cost[b] : a > b);
  // Busy workers are [finishTime, worker]: the earliest finish comes out first.
  const sooner = (a, b) => a[0] < b[0];
  const leftWait = [], rightWait = [], leftBusy = [], rightBusy = [];
  for (let i = 0; i < k; i++) push(leftWait, i, slower);
  let now = 0;
  let remaining = n;
  for (;;) {
    while (leftBusy.length > 0 && leftBusy[0][0] <= now) push(leftWait, pop(leftBusy, sooner)[1], slower);
    while (rightBusy.length > 0 && rightBusy[0][0] <= now) push(rightWait, pop(rightBusy, sooner)[1], slower);
    if (rightWait.length > 0) {
      const worker = pop(rightWait, slower);
      now += time[worker][2];
      if (remaining === 0 && rightWait.length === 0 && rightBusy.length === 0) return now;
      push(leftBusy, [now + time[worker][3], worker], sooner);
    } else if (remaining > 0 && leftWait.length > 0) {
      const worker = pop(leftWait, slower);
      now += time[worker][0];
      remaining--;
      push(rightBusy, [now + time[worker][1], worker], sooner);
    } else {
      let next = rightBusy.length > 0 ? rightBusy[0][0] : Infinity;
      if (remaining > 0 && leftBusy.length > 0) next = Math.min(next, leftBusy[0][0]);
      now = next;
    }
  }
}

