function findCrossingTime(n, k, time) {
  // Event-driven state machine: every worker is in one state until the minute stored in until[i].
  const state = Array(k).fill('left');
  const until = Array(k).fill(0);
  const weight = i => time[i][0] + time[i][2];
  const slowest = ids => ids.reduce((a, b) => (weight(b) > weight(a) || (weight(b) === weight(a) && b > a) ? b : a));
  let sent = 0, arrived = 0, bridgeFreeAt = 0, t = 0;
  for (;;) {
    for (let i = 0; i < k; i++) {
      if (until[i] > t) continue;
      if (state[i] === 'toRight') { state[i] = 'pick'; until[i] = t + time[i][1]; }
      else if (state[i] === 'pick') state[i] = 'right';
      else if (state[i] === 'toLeft') {
        arrived++;
        if (arrived === n) return t;
        state[i] = 'put'; until[i] = t + time[i][3];
      } else if (state[i] === 'put') state[i] = 'left';
    }
    if (bridgeFreeAt <= t) {
      const right = [], left = [];
      for (let i = 0; i < k; i++) {
        if (state[i] === 'right') right.push(i);
        else if (state[i] === 'left') left.push(i);
      }
      if (right.length) { const i = slowest(right); state[i] = 'toLeft'; until[i] = bridgeFreeAt = t + time[i][2]; }
      else if (sent < n && left.length) { const i = slowest(left); sent++; state[i] = 'toRight'; until[i] = bridgeFreeAt = t + time[i][0]; }
    }
    let next = Infinity;
    for (let i = 0; i < k; i++) if (until[i] > t) next = Math.min(next, until[i]);
    t = next;
  }
}

