function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let n, k, top;
  if (size === 'large') {
    const shape = pick(0, 3);
    if (shape === 0) { n = 10000; k = 2000; }
    else if (shape === 1) { n = 10000; k = pick(1, 12); }
    else if (shape === 2) { n = pick(1, 60); k = 2000; }
    else { n = pick(1000, 10000); k = pick(50, 2000); }
    top = rand() < 0.3 ? pick(2, 6) : 1000;
  } else {
    n = pick(1, 7);
    k = pick(1, 4);
    top = rand() < 0.5 ? 3 : 10;
  }
  const time = Array.from({ length: k }, () => [pick(1, top), pick(1, top), pick(1, top), pick(1, top)]);
  return [n, k, time];
}
